// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.lwjgl.util.lmdb.LMDB.MDB_MAP_FULL;
import static org.lwjgl.util.lmdb.LMDB.mdb_txn_abort;

import java.io.File;
import java.io.IOException;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.Executors;

import org.eclipse.rdf4j.sail.lmdb.config.FrontierEstimatorMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.frontier.FrontierMutation;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;

class TripleStoreWriteRouteReplayCompositionTest {
	private static final long[] SUBJECTS = { 101L, 102L, 101L };
	private static final long[] PREDICATES = { 201L, 201L, 201L };
	private static final long[] OBJECTS = { 301L, 302L, 301L };
	private static final long[] CONTEXTS = { 0L, 99L, 0L };

	@ParameterizedTest
	@EnumSource(WriteRoute.class)
	void commitCapacityReplayReconstructsPhysicalJournalWithoutRepeatingLogicalFanOut(WriteRoute route,
			@TempDir Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,posc,psoc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE);
		double before;
		try (CommitFullTripleStore store = new CommitFullTripleStore(directory.toFile(), config)) {
			store.startTransaction();
			write(store, route);
			assertTrue(store.storeTriple(103L, 201L, 303L, 0L, true));
			before = store.meanFanOut(201L, true, true).orElseThrow();
			store.failNextCommit = true;
			store.commit();
			assertTrue(store.replays > 0, "real native abort and map-growth replay must occur");
			assertEquals(before, store.meanFanOut(201L, true, true).orElseThrow(),
					"replaying the physical prefix must not publish logical fan-out twice");
			assertJournal(store);
		}
		try (TripleStore reopened = new TripleStore(directory.toFile(), config, null)) {
			assertJournal(reopened);
			assertTrue(reopened.meanFanOut(201L, true, true).isEmpty(),
					"fan-out statistics are process-local advisory state, not persisted across reopen");
		}
	}

	private static void assertJournal(TripleStore store) throws IOException {
		var mutations = store.readFrontierMutationsAfter(0L, 10);
		assertEquals(List.of(1L, 2L, 3L), mutations.stream().map(FrontierMutation::sequence).toList());
		assertEquals(List.of(101L, 102L, 103L), mutations.stream().map(FrontierMutation::subjectId).sorted().toList());
		assertTrue(mutations.stream().allMatch(mutation -> mutation.insertion() && mutation.explicit()));
		assertEquals(3L, store.frontierMutationJournalState().latestSequence());
		assertEquals(0L, store.frontierMutationJournalState().gapThroughSequence());
		try (var txn = store.getTxnManager().createReadTxn();
				var rows = store.getTriples(txn, -1L, -1L, -1L, -1L, true)) {
			int count = 0;
			while (rows.next() != null) {
				count++;
			}
			assertEquals(3, count);
		}
	}

	private static void write(TripleStore store, WriteRoute route) throws Exception {
		switch (route) {
		case SCALAR -> {
			assertTrue(store.storeTriple(SUBJECTS[0], PREDICATES[0], OBJECTS[0], CONTEXTS[0], true));
			assertTrue(store.storeTriple(SUBJECTS[1], PREDICATES[1], OBJECTS[1], CONTEXTS[1], true));
			assertFalse(store.storeTriple(SUBJECTS[2], PREDICATES[2], OBJECTS[2], CONTEXTS[2], true));
		}
		case ALIGNED -> store.storeTriplesAligned(SUBJECTS, PREDICATES, OBJECTS, CONTEXTS, 3, true);
		case PREPARED -> {
			try (var executor = Executors.newFixedThreadPool(3)) {
				var prepared = store.prepareSecondaryIndexesAsync(executor, SUBJECTS, PREDICATES, OBJECTS, CONTEXTS, 3);
				try {
					store.storePreparedTriples(SUBJECTS, PREDICATES, OBJECTS, CONTEXTS, 3, true, false, null,
							prepared.awaitMain(), prepared::await);
				} finally {
					prepared.cancel();
				}
			}
		}
		case GLOBAL -> {
			assertTrue(store.supportsGlobalPreparedOrder(), "the fixture must execute the genuine global writer");
			assertTrue(store.isEmpty(), "global fresh import starts from a genuinely empty store");
			int[] quads = { 0, 2, 3, -1, 1, 2, 4, 5, 0, 2, 3, -1 };
			long[] values = { 101L, 102L, 201L, 301L, 302L, 99L };
			try (var executor = Executors.newFixedThreadPool(3)) {
				var prepared = store.prepareGlobalIndexOrdersAsync(executor, quads, values, 3);
				try {
					assertEquals(2, store.storeGloballyOrderedFreshTriples(quads, values, 3, prepared, executor));
				} finally {
					prepared.cancel();
				}
			}
		}
		}
	}

	private static final class CommitFullTripleStore extends TripleStore {
		boolean failNextCommit;
		int replays;

		CommitFullTripleStore(File directory, LmdbStoreConfig config) throws IOException {
			super(directory, config, null);
		}

		@Override
		int commitWriteTransaction(long transaction) {
			if (failNextCommit) {
				failNextCommit = false;
				mdb_txn_abort(transaction);
				return MDB_MAP_FULL;
			}
			return super.commitWriteTransaction(transaction);
		}

		@Override
		protected void afterMapGrowthReplay() {
			replays++;
		}
	}

	enum WriteRoute {
		SCALAR,
		ALIGNED,
		PREPARED,
		GLOBAL
	}
}
